css:
@font-face {
  font-family: 'Golos Text'; font-weight: 400 900; font-style: normal; font-display: swap;
  src: url('../assets/fonts/golos-text-cyrillic-ext-wght-normal.woff2') format('woff2');
  unicode-range: U+0460-052F,U+1C80-1C8A,U+20B4,U+2DE0-2DFF,U+A640-A69F,U+FE2E-FE2F;
}
@font-face {
  font-family: 'Golos Text'; font-weight: 400 900; font-style: normal; font-display: swap;
  src: url('../assets/fonts/golos-text-cyrillic-wght-normal.woff2') format('woff2');
  unicode-range: U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116;
}
@font-face {
  font-family: 'Golos Text'; font-weight: 400 900; font-style: normal; font-display: swap;
  src: url('../assets/fonts/golos-text-latin-wght-normal.woff2') format('woff2');
  unicode-range: U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
:root {
  --bg: #f8faff; --surface: #fff; --text: #111111; --heading: #0b0f19; --muted: #242424; --caption: #333333;
  --ink: #101828; /* Reserved for the existing Canvas palette. */
  --blue: #155eef; --blue-dark: #1048c5; --accent: #635bce; --accent-light: #c4beff;
  --navy: #102a4c; --navy-deep: #0b203b; --on-navy: #fff; --on-navy-muted: #ffffff;
  --line: #d8e2f0; --navy-line: #48617c; --pale: #edf2ff; --blue-wash: #deebff;
  --art-lilac: #ebe9ff; --art-paper: #fff; --art-line: #9cafd0;
  --white: #fff; --cursor-fill: rgb(21 94 239 / .09); --overlay: rgb(11 32 59 / .42);
  --shadow: 0 8px 24px rgb(16 42 76 / .07); --font: 'Golos Text', 'Segoe UI', sans-serif;
  --ease: cubic-bezier(.22,1,.36,1);
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 96px; -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--text); font: 400 18px/1.55 var(--font); -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; }
a, button { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
button { font: inherit; color: inherit; cursor: pointer; border: 0; }
p, h1, h2, h3 { margin: 0; }
h2, h3 { color: var(--heading); }
.hero-copy h1, .contacts h2 { color: var(--on-navy); }
svg { display: block; flex-shrink: 0; }
[hidden] { display: none !important; }
::selection { background: var(--accent-light); color: var(--text); }
:focus-visible { outline: 3px solid var(--blue); outline-offset: 5px; border-radius: 3px; }
.hero-copy :focus-visible, .contacts :focus-visible { outline-color: var(--accent-light); }
main:focus { outline: none; }
.svg-definitions { position: absolute; width: 0; height: 0; overflow: hidden; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.container { width: min(1280px, calc(100% - 80px)); margin-inline: auto; }
.skip-link { position: fixed; top: 10px; left: 16px; z-index: 100; padding: 10px 16px; background: var(--navy); color: var(--white); transform: translateY(-160%); }
.skip-link:focus { transform: none; }
.site-header { position: sticky; top: 0; z-index: 30; background: var(--bg); border-bottom: 1px solid transparent; }
.site-header.scrolled { border-color: var(--line); }
.header-inner { min-height: 78px; display: flex; align-items: center; gap: 25px; }
.brand { color: var(--navy); display: inline-flex; align-items: center; gap: 5px; font-size: 28px; font-weight: 750; letter-spacing: -.055em; flex-shrink: 0; }
.brand svg { color: var(--blue); width: 37px; height: 37px; }
.brand-period { color: var(--blue); }
.header-actions { display: flex; align-items: center; gap: 20px; margin-left: auto; }
.language-switch { display: flex; align-items: center; gap: 5px; font-size: 13px; font-weight: 600; }
.language-switch a { min-width: 31px; min-height: 44px; display: grid; place-items: center; }
.language-switch a[aria-current=true] { color: var(--blue); }
.language-switch a[aria-current=false], .language-switch>span { color: var(--caption); }
.language-switch>span { font-weight: 400; }
.button { min-height: 56px; display: inline-flex; align-items: center; justify-content: center; gap: 17px; padding: 14px 23px; border: 1px solid transparent; border-radius: 7px; font-size: 17px; font-weight: 600; line-height: 1.4; text-align: center; }
.button svg { width: 21px; height: 21px; stroke: currentColor; fill: none; stroke-width: 1.7; }
.button-primary { background: var(--blue); border-color: var(--blue); color: var(--white); }
.button-primary:hover { background: var(--blue-dark); border-color: var(--blue-dark); }
.button-outline { color: var(--blue); background: var(--surface); border-color: var(--blue); }
.button-outline:hover { background: var(--pale); }
.button-small { min-height: 46px; padding: 10px 15px; font-size: 16px; gap: 10px; }
.button-arrow { display: inline-block; }
.button-order { min-height: 62px; width: min(320px, 100%); font-size: 19px; gap: 29px; }
.hero { padding-top: 12px; }
.hero-layout { display: grid; grid-template-columns: 1.08fr 1fr; border: 1px solid var(--line); border-radius: 12px; overflow: clip; background: var(--surface); }
.hero-copy { background: var(--navy); color: var(--on-navy); padding: 35px 37px; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; }
.eyebrow { font-size: 13px; font-weight: 600; letter-spacing: .1em; }
.hero-copy .eyebrow { color: var(--on-navy-muted); margin-bottom: 20px; }
h1 { font-size: clamp(39px, 4.2vw, 58px); line-height: 1.07; font-weight: 700; letter-spacing: -.05em; }
h1>[data-i18n] { display: block; }
.text-accent { color: var(--on-navy); }
.hero-description { max-width: 470px; color: var(--on-navy-muted); font-size: 18px; line-height: 1.6; margin-top: 20px; }
.hero-actions { width: 100%; display: flex; justify-content: center; margin-top: 25px; }
.network-panel { min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 17px 5px 13px; }
.network-caption { display: flex; align-items: center; justify-content: center; gap: 10px; font-size: 14px; font-weight: 500; }
.network-caption>span:first-child { color: var(--accent); font-size: 23px; }
.network-stage { position: relative; height: 345px; width: 100%; overflow: clip; touch-action: pan-y; user-select: none; cursor: grab; background: radial-gradient(ellipse at center, var(--blue-wash), var(--surface) 72%); }
.network-stage.is-dragging { cursor: grabbing; }
.network-stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; }
.network-stage.ready canvas { opacity: 1; }
.network-fallback { position: absolute; inset: 10%; padding: 30px; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 15px; border: 1px solid var(--line); border-radius: 50%; color: var(--blue-dark); font-size: 16px; }
.network-fallback strong { font-size: 25px; color: var(--ink); }
.ready .network-fallback { visibility: hidden; }
.network-bottom { display: flex; align-items: center; justify-content: center; gap: 13px; min-height: 36px; }
.network-hint { font-size: 13px; color: var(--caption); }
.motion-toggle { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; background: var(--surface); }
.motion-toggle:hover { border-color: var(--blue); }
.pause-icon { width: 7px; height: 9px; border-inline: 2px solid var(--muted); }
.motion-toggle[aria-pressed=true] .pause-icon { width: 0; height: 0; border: 5px solid transparent; border-left: 7px solid var(--muted); margin-left: 5px; }
.section { padding-block: 34px; }
h2 { font-size: clamp(28px, 2.65vw, 38px); line-height: 1.18; font-weight: 650; letter-spacing: -.04em; text-wrap: balance; }
.services h2 { margin-bottom: 22px; }
.services-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.service-card { position: relative; padding: 16px 22px; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; display: grid; grid-template-columns: 68px minmax(0, 1fr); column-gap: 12px; row-gap: 8px; align-content: start; }
.service-card:hover, .service-card:focus-within { border-color: var(--blue); background: var(--pale); box-shadow: var(--shadow); }
.service-art { width: 68px; height: 41px; align-self: center; overflow: visible; fill: none; stroke: var(--blue); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.art-wash { fill: var(--blue-wash); stroke: none; }
.art-lilac { fill: var(--art-lilac); stroke: none; }
.art-paper { fill: var(--art-paper); }
.art-fill { fill: var(--blue); stroke: none; }
.art-accent { stroke: var(--accent); }
.art-accent-fill { fill: var(--accent); stroke: none; }
.art-rule { stroke: var(--art-line); }
.service-card h3 { font-size: 19px; line-height: 1.35; font-weight: 600; letter-spacing: -.02em; align-self: center; }
.service-card p { grid-column: 1 / -1; font-size: 16.5px; line-height: 1.55; color: var(--muted); padding-right: 8px; }
.service-link { position: absolute; inset: 0; border-radius: inherit; }
.service-link svg { position: absolute; width: 16px; height: 16px; right: 10px; bottom: 10px; fill: none; stroke: var(--blue); stroke-width: 1.8; }
.process { padding-top: 3px; padding-bottom: 33px; }
.process h2 { font-size: clamp(27px, 2.25vw, 33px); margin-bottom: 24px; }
.timeline { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, 1fr); }
.timeline-step { border-top: 1px solid var(--line); position: relative; padding: 17px 25px 0 0; }
.timeline-step::before { content: ''; position: absolute; top: -4px; left: 0; width: 7px; height: 7px; background: var(--accent); border-radius: 50%; }
.timeline-step::after { content: ''; position: absolute; top: -1px; left: 0; right: 0; height: 2px; background: var(--accent); transform-origin: left; }
.timeline-step:last-child::after { right: calc(100% - 32px); }
.step-number { font-size: 13px; font-weight: 600; color: var(--caption); display: inline-block; margin-bottom: 7px; }
.timeline-step h3 { font-size: 20px; font-weight: 600; line-height: 1.35; margin-bottom: 7px; }
.timeline-step p { font-size: 17px; line-height: 1.5; color: var(--muted); max-width: 285px; }
.contacts { padding-top: 31px; background: var(--navy); color: var(--on-navy); }
.contact-top { display: flex; align-items: center; justify-content: space-between; gap: 35px; }
.contact-top>div { max-width: 710px; }
.contact-top h2 { font-size: clamp(31px, 3vw, 42px); }
.contact-description { margin-top: 13px; color: var(--on-navy-muted); font-size: 18px; line-height: 1.55; max-width: 700px; }
.contact-cta { flex-shrink: 0; font-size: 17px; min-height: 58px; max-width: 375px; }
.contact-details { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 25px; padding-block: 22px 15px; margin-top: 23px; border-top: 1px solid var(--navy-line); }
.contact-detail { min-width: 0; }
.contact-detail>p { font-size: 14px; color: var(--on-navy-muted); margin-bottom: 6px; }
.contact-detail>a, .contact-unset { color: var(--on-navy); font-size: 16px; line-height: 1.5; overflow-wrap: anywhere; }
.contact-detail>a:hover { color: var(--on-navy); text-decoration: underline; }
.contact-unset { color: var(--on-navy-muted); }
.preview-notice { display: flex; align-items: center; gap: 8px; color: var(--on-navy-muted); font-size: 13px; padding-bottom: 13px; }
.preview-notice strong { font-weight: 400; }
.preview-notice>span { width: 5px; height: 5px; border-radius: 50%; background: var(--accent-light); }
.site-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding-block: 12px; border-top: 1px solid var(--navy-line); font-size: 13px; color: var(--on-navy-muted); }
.back-top { color: var(--on-navy); display: inline-flex; align-items: center; gap: 9px; min-height: 36px; }
.back-top svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 1.5; }
dialog { border: 1px solid var(--line); border-radius: 10px; background: var(--surface); color: var(--text); width: min(460px, calc(100% - 32px)); max-height: calc(100% - 32px); padding: 0; box-shadow: var(--shadow); }
dialog::backdrop { background: var(--overlay); }
.dialog-content { padding: 30px; }
.dialog-brand { width: 40px; height: 40px; color: var(--blue); margin-bottom: 18px; }
.dialog-content .eyebrow { margin-bottom: 15px; color: var(--muted); }
.dialog-content h2 { font-size: 30px; }
.dialog-content>p:last-of-type { font-size: 17px; color: var(--muted); margin-block: 18px 23px; }
.dialog-content .button { width: 100%; }
.noscript-note { font-size: 15px; padding: 14px 20px; color: var(--text); background: var(--pale); text-align: center; }
.cursor-layer { position: fixed; inset: 0; z-index: 99; pointer-events: none; overflow: clip; contain: strict; }
.custom-cursor { display: none; position: fixed; top: 0; left: 0; width: 26px; height: 26px; border: 1px solid var(--blue); border-radius: 50%; pointer-events: none; opacity: 0; transition: width .2s, height .2s, opacity .15s, background .2s; }
.custom-cursor>span { position: absolute; width: 4px; height: 4px; top: 50%; left: 50%; background: var(--blue); border-radius: 50%; transform: translate(-50%, -50%); }
.custom-cursor.active { width: 39px; height: 39px; background: var(--cursor-fill); }
.custom-cursor.network-mode { width: 43px; height: 43px; background: var(--blue-wash); }
.custom-cursor.network-mode::after, .custom-cursor.card-mode::after { content: '↔'; position: absolute; inset: 0; display: grid; place-items: center; color: var(--blue-dark); font-size: 20px; }
.custom-cursor.card-mode::after { content: '↗'; font-size: 17px; }
.custom-cursor.network-mode>span, .custom-cursor.card-mode>span { display: none; }
.custom-cursor.drag-mode { width: 35px; height: 35px; }
.custom-cursor.text-mode { opacity: 0 !important; }
.custom-cursor.dark-mode { border-color: var(--accent-light); }
.custom-cursor.dark-mode>span { background: var(--accent-light); }
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .cursor-enabled .custom-cursor { display: block; }
  .cursor-enabled, .cursor-enabled a, .cursor-enabled button, .cursor-enabled .network-stage { cursor: none; }
  .cursor-enabled input, .cursor-enabled textarea, .cursor-enabled [contenteditable=true] { cursor: text; }
}
@media (prefers-reduced-motion: no-preference) {
  .service-art { transition: transform .25s var(--ease); }
  .service-card:hover .service-art, .service-card:focus-within .service-art { transform: translateY(-2px); }
  .button, .service-card { transition: background .2s, border-color .2s, translate .3s var(--ease); }
  .button:hover { translate: 0 -2px; }
  .button-arrow { transition: transform .3s var(--ease); }
  .word { display: inline-block; animation: text-enter .55s var(--ease) both; animation-delay: calc(var(--word-index) * 45ms); }
  .reveal.is-observed { opacity: 0; transform: translateY(14px); transition: opacity .5s var(--ease), transform .5s var(--ease); transition-delay: var(--delay, 0ms); }
  .reveal.is-visible { opacity: 1; transform: none; }
  .timeline.is-observed .timeline-step::after { transform: scaleX(0); transition: transform .5s var(--ease); transition-delay: calc(var(--step) * 130ms); }
  .timeline.is-visible .timeline-step::after { transform: scaleX(1); }
}
@keyframes text-enter { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@media (max-width: 1199px) {
  .container { width: calc(100% - 56px); }
  .header-inner { gap: 18px; }
  .header-actions { gap: 14px; }
  .brand { font-size: 26px; }
  .hero-copy { padding: 29px 26px; }
  .hero-description { font-size: 17px; }
  .network-stage { height: 325px; }
  .service-card { padding: 14px 19px; }
  .service-card h3 { font-size: 18px; }
  .service-card p { font-size: 16px; }
  .contact-top>div { max-width: 560px; }
  .contact-cta { max-width: 330px; }
}
@media (max-width: 999px) {
  html { scroll-padding-top: 92px; }
  .header-inner { min-height: 76px; }
  .header-actions { margin-left: auto; gap: 18px; }
  .hero-layout { grid-template-columns: 1.03fr 1fr; }
  .hero-copy { padding: 26px 20px; }
  h1 { font-size: clamp(34px, 4.5vw, 43px); }
  .hero-copy .eyebrow { font-size: 12px; margin-bottom: 16px; }
  .hero-description { font-size: 17px; margin-top: 17px; }
  .hero-actions { margin-top: 21px; }
  .button-order { font-size: 18px; min-height: 58px; }
  .network-stage { height: 310px; }
  .network-hint { display: none; }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .service-card h3 { font-size: 19px; }
  .service-card p { font-size: 16.5px; }
  .timeline-step { padding-right: 20px; }
  .timeline-step h3 { font-size: 19px; }
  .contact-top { align-items: flex-start; }
  .contact-top>div { max-width: 470px; }
  .contact-cta { max-width: 285px; font-size: 16px; padding-inline: 17px; }
  .contact-details { gap: 18px; }
}
@media (max-width: 767px) {
  html { scroll-padding-top: 143px; }
  .container { width: calc(100% - 32px); }
  .header-inner { display: grid; grid-template-columns: 1fr auto; gap: 4px 7px; padding-block: 7px 9px; min-height: 0; }
  .brand { grid-column: 1; font-size: 25px; }
  .brand svg { width: 31px; height: 31px; }
  .header-actions { display: contents; }
  .language-switch { grid-column: 2; font-size: 13px; gap: 3px; }
  .header-actions>.button { grid-column: 1 / -1; grid-row: 2; width: 100%; font-size: 16px; min-height: 43px; padding-block: 9px; }
  .hero { padding-top: 9px; }
  .hero-layout { grid-template-columns: 1fr; }
  .hero-copy { padding: 27px 24px; }
  .hero-copy .eyebrow { font-size: 12px; margin-bottom: 16px; }
  h1 { font-size: clamp(36px, 8.9vw, 54px); line-height: 1.1; }
  .hero-description { font-size: 18px; line-height: 1.55; margin-top: 17px; max-width: 530px; }
  .hero-actions { margin-top: 21px; }
  .button-order { font-size: 18px; width: min(310px, 100%); min-height: 59px; }
  .network-panel { padding-block: 9px; }
  .network-caption { font-size: 14px; }
  .network-stage { height: clamp(255px, 73vw, 340px); cursor: auto; }
  .network-bottom { min-height: 34px; }
  .section { padding-block: 29px; }
  h2 { font-size: clamp(28px, 6.8vw, 36px); }
  .services h2 { margin-bottom: 19px; }
  .services-grid { grid-template-columns: 1fr; gap: 10px; }
  .service-card { padding: 13px 19px; row-gap: 5px; }
  .service-card h3 { font-size: 19px; }
  .service-card p { font-size: 17px; line-height: 1.5; padding-right: 7px; }
  .process { padding-top: 0; padding-bottom: 28px; }
  .process h2 { font-size: 28px; margin-bottom: 20px; }
  .timeline { grid-template-columns: 1fr; }
  .timeline-step { display: grid; grid-template-columns: 24px minmax(0, 1fr); column-gap: 11px; border-top: 0; border-left: 1px solid var(--line); padding: 0 0 18px 18px; }
  .timeline-step::before { top: 8px; left: -4px; }
  .timeline-step::after { top: 8px; bottom: 0; left: -1px; width: 2px; height: auto; right: auto; transform-origin: top; }
  .timeline-step:last-child::after { display: none; }
  .timeline-step:last-child { padding-bottom: 0; }
  .step-number { grid-column: 1; grid-row: 1; font-size: 13px; margin: 4px 0 0; }
  .timeline-step h3 { grid-column: 2; grid-row: 1; font-size: 19px; margin-bottom: 5px; }
  .timeline-step p { grid-column: 2; font-size: 17px; line-height: 1.5; max-width: 520px; }
  .timeline.is-observed .timeline-step::after { transform: scaleY(0); }
  .timeline.is-visible .timeline-step::after { transform: scaleY(1); }
  .contacts { padding-top: 27px; }
  .contact-top { display: block; }
  .contact-top h2 { font-size: clamp(31px, 7.5vw, 39px); }
  .contact-top>div { max-width: none; }
  .contact-description { font-size: 18px; line-height: 1.5; margin-top: 13px; }
  .contact-cta { max-width: none; width: 100%; margin-top: 19px; min-height: 58px; font-size: 16px; }
  .contact-details { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px 18px; margin-top: 21px; padding-block: 18px; }
  .contact-detail>p { font-size: 14px; }
  .contact-detail>a, .contact-unset { font-size: 15px; }
  .site-footer { align-items: flex-start; gap: 12px; font-size: 13px; }
  .site-footer>p { max-width: 76%; }
  .back-top { min-height: 30px; gap: 5px; }
  .dialog-content { padding: 25px; }
}
@media (max-width: 374px) {
  .hero-copy { padding-inline: 19px; }
  .hero-description { font-size: 17px; }
  .service-card { padding-inline: 16px; }
  .service-card h3 { font-size: 18px; }
  .service-card p { font-size: 16.5px; }
  .contact-description { font-size: 17px; }
  .contact-cta { padding-inline: 14px; gap: 10px; }
  .contact-details { gap: 18px 14px; }
  .contact-detail>a, .contact-unset { font-size: 14px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
  .reveal { opacity: 1 !important; transform: none !important; }
  .button, .button-arrow { translate: none !important; transform: none !important; }
  .custom-cursor { display: none !important; }
  .network-stage { cursor: default; }
}
@media print {
  .site-header, .network-panel, .hero-actions, .service-link, .contact-cta, .cursor-layer, .back-top { display: none !important; }
  .container { width: 100%; }
  .hero-layout { display: block; border: 0; }
  .hero-copy, .contacts { background: var(--white); color: var(--text); }
  .hero-copy h1, .hero-copy .text-accent, .contacts h2 { color: var(--heading); }
  .hero-description, .hero-copy .eyebrow, .contact-description, .contact-detail>p, .contact-unset, .site-footer, .preview-notice { color: var(--text); }
  .hero-copy { padding: 15px; }
  .section, .contacts { padding-block: 18px; }
  .reveal { opacity: 1 !important; transform: none !important; }
  .service-card { break-inside: avoid; }
}
